import React, { useState, useRef, useCallback, useEffect } from 'react';
import { useGameStore } from '../../store';
import { REGION_IDS } from '../../data/initialState';
import { orderPositions, towerPositions, unrestPositions, elephantPositions } from '../../data/mapCoordinates';

import baseMapImage from '../../assets/images/map/india_base.png';

import punjabDetailed from '../../assets/images/map/regions/punjab_detailed.png';
import delhiDetailed from '../../assets/images/map/regions/delhi_detailed.png';
import bengalDetailed from '../../assets/images/map/regions/bengal_detailed.png';
import bombayDetailed from '../../assets/images/map/regions/bombay_detailed.png';
import marathaDetailed from '../../assets/images/map/regions/maratha_detailed.png';
import hyderabadDetailed from '../../assets/images/map/regions/hyderabad_detailed.png';
import mysoreDetailed from '../../assets/images/map/regions/mysore_detailed.png';
import madrasDetailed from '../../assets/images/map/regions/madras_detailed.png';

import punjabRegion from '../../assets/images/map/regions/punjab.png';
import delhiRegion from '../../assets/images/map/regions/delhi.png';
import bengalRegion from '../../assets/images/map/regions/bengal.png';
import bombayRegion from '../../assets/images/map/regions/bombay.png';
import marathaRegion from '../../assets/images/map/regions/maratha.png';
import hyderabadRegion from '../../assets/images/map/regions/hyderabad.png';
import mysoreRegion from '../../assets/images/map/regions/mysore.png';
import madrasRegion from '../../assets/images/map/regions/madras.png';

import closedOrderImg from '../../assets/images/pieces/closed_order.png';
import governorOverlayImg from '../../assets/images/pieces/governor_overlay.png';
import towerSimpleImg from '../../assets/images/pieces/tower_simple.png';
import unrestImg from '../../assets/images/pieces/unrest.png';
import elephantImg from '../../assets/images/pieces/elephant.png';
import flagImg from '../../assets/images/pieces/flag.png';
import flagStarImg from '../../assets/images/pieces/flag_star.png';
import flagGoldImg from '../../assets/images/pieces/flag_gold.png';
import flagGoldStarImg from '../../assets/images/pieces/flag_star_gold.png';
import flagBronzeImg from '../../assets/images/pieces/flag_bronze.png';
import flagBronzeStarImg from '../../assets/images/pieces/flag_star_bronze.png';
//regions in base64 

const REGIONS_MAP_BASE64 = 'data:image/png;base64,';

interface MapViewProps {
  selectedRegion: string | null;
  onRegionSelect: (regionId: string | null) => void;
  currentPhase: string;
}

// Map colors to region IDs
const COLOR_TO_REGION: Record<string, string> = {
  '696e76': REGION_IDS.PUNJAB,  
  'a3998f': REGION_IDS.DELHI,      
  'be856b': REGION_IDS.BENGAL,    
  '99b0a7': REGION_IDS.BOMBAY,    
  'c89564': REGION_IDS.MARATHA,    
  'aeaf87': REGION_IDS.HYDERABAD, 
  'c5baa1': REGION_IDS.MYSORE,     
  'e8c07e': REGION_IDS.MADRAS,     
};

const MapView: React.FC<MapViewProps> = ({ selectedRegion, onRegionSelect, currentPhase }) => {
  const { gameState, updateOrder } = useGameStore();
  const [isZoomed, setIsZoomed] = useState(false);
  const [hoveredRegion, setHoveredRegion] = useState<string | null>(null);
  const [imageData, setImageData] = useState<ImageData | null>(null);
  const [isImageLoaded, setIsImageLoaded] = useState(false);
  const [displayRect, setDisplayRect] = useState({ left: 0, top: 0, width: 0, height: 0 });
  const [naturalSize, setNaturalSize] = useState({ width: 0, height: 0 });
  const [containerSize, setContainerSize] = useState({ width: 0, height: 0 });
  
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const baseImageRef = useRef<HTMLImageElement>(null);
  const resizeObserverRef = useRef<ResizeObserver | null>(null);


  // Map region IDs to their detailed images
  const detailedRegionImages: Record<string, string> = {
    [REGION_IDS.PUNJAB]: punjabDetailed,
    [REGION_IDS.DELHI]: delhiDetailed,
    [REGION_IDS.BENGAL]: bengalDetailed,
    [REGION_IDS.BOMBAY]: bombayDetailed,
    [REGION_IDS.MARATHA]: marathaDetailed,
    [REGION_IDS.HYDERABAD]: hyderabadDetailed,
    [REGION_IDS.MYSORE]: mysoreDetailed,
    [REGION_IDS.MADRAS]: madrasDetailed,
  };

  // Map region IDs to their overlay images
  const regionOverlayImages: Record<string, string> = {
    [REGION_IDS.PUNJAB]: punjabRegion,
    [REGION_IDS.DELHI]: delhiRegion,
    [REGION_IDS.BENGAL]: bengalRegion,
    [REGION_IDS.BOMBAY]: bombayRegion,
    [REGION_IDS.MARATHA]: marathaRegion,
    [REGION_IDS.HYDERABAD]: hyderabadRegion,
    [REGION_IDS.MYSORE]: mysoreRegion,
    [REGION_IDS.MADRAS]: madrasRegion,
  };

  // Calculate the actual displayed area of the base map
  const calculateDisplayRect = useCallback(() => {
    if (!mapContainerRef.current || !baseImageRef.current) return;

    const container = mapContainerRef.current;
    const img = baseImageRef.current;
    
    const containerWidth = container.clientWidth;
    const containerHeight = container.clientHeight;
    const imgRatio = img.naturalWidth / img.naturalHeight;
    const containerRatio = containerWidth / containerHeight;

    let displayedWidth, displayedHeight, left, top;

    if (containerRatio > imgRatio) {
      // Container is wider than image - image height matches container
      displayedHeight = containerHeight;
      displayedWidth = containerHeight * imgRatio;
      left = (containerWidth - displayedWidth) / 2;
      top = 0;
    } else {
      // Container is taller than image - image width matches container
      displayedWidth = containerWidth;
      displayedHeight = containerWidth / imgRatio;
      left = 0;
      top = (containerHeight - displayedHeight) / 2;
    }

    setDisplayRect({
      left,
      top,
      width: displayedWidth,
      height: displayedHeight
    });

    setContainerSize({
      width: containerWidth,
      height: containerHeight
    });
  }, []);

  // Convert percentage coordinates to absolute pixels
  const getAbsolutePosition = useCallback((pos: { x: number; y: number }) => {
    return {
      x: displayRect.left + (pos.x / 100) * displayRect.width,
      y: displayRect.top + (pos.y / 100) * displayRect.height
    };
  }, [displayRect]);

  // Handle order click
  const handleOrderClick = useCallback((orderId: string, event: React.MouseEvent) => {
    event.stopPropagation(); // Prevent region selection
    if (currentPhase === 'company') {
      const order = gameState.orders[orderId];
      if (order) {
        updateOrder(orderId, { open: !order.open });
      }
    }
  }, [currentPhase, gameState.orders, updateOrder]);

  // Initialize canvas with the regions image
  const initCanvas = useCallback(() => {
    console.log(naturalSize,containerSize);
    if (!canvasRef.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Create image for regions map
    const regionsImage = new Image();
    regionsImage.onload = () => {
      // Set canvas to match the actual displayed size of the base map
      canvas.width = displayRect.width;
      canvas.height = displayRect.height;
      
      // Clear canvas
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      
      // Draw regions image scaled to match the base map display
      ctx.drawImage(regionsImage, 0, 0, canvas.width, canvas.height);
      
      // Get image data for hit detection
      const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      setImageData(imgData);
      setIsImageLoaded(true);
    };
    regionsImage.src = REGIONS_MAP_BASE64;
  }, [displayRect]);

  // Set up ResizeObserver to watch for container size changes
  useEffect(() => {
    if (!mapContainerRef.current) return;

    resizeObserverRef.current = new ResizeObserver((entries) => {
      for (const entry of entries) {
        if (entry.target === mapContainerRef.current) {
          calculateDisplayRect();
        }
      }
    });

    resizeObserverRef.current.observe(mapContainerRef.current);

    return () => {
      if (resizeObserverRef.current) {
        resizeObserverRef.current.disconnect();
      }
    };
  }, [calculateDisplayRect]);

  // Also recalculate on window resize as a fallback
  useEffect(() => {
    const handleWindowResize = () => {
      calculateDisplayRect();
    };

    window.addEventListener('resize', handleWindowResize);
    return () => window.removeEventListener('resize', handleWindowResize);
  }, [calculateDisplayRect]);

  // Reinitialize canvas when display rect changes
  useEffect(() => {
    //temporarily unselecting region here.
    if (currentPhase === 'event') {
      onRegionSelect(null);
    }
    if (displayRect.width > 0 && displayRect.height > 0) {
      initCanvas();
    }
  }, [displayRect, initCanvas]);

  // Recalculate when the game state changes (orders, towers, etc.)
  useEffect(() => {
    calculateDisplayRect();
  }, [gameState.orders, gameState.regions, calculateDisplayRect]);

  // Get region from pixel color
  const getRegionFromPixel = useCallback((x: number, y: number): string | null => {
    if (!imageData || !canvasRef.current) return null;

    const pixelPos = 4 * (x + canvasRef.current.width * y);
    const r = imageData.data[pixelPos].toString(16).padStart(2, '0');
    const g = imageData.data[pixelPos + 1].toString(16).padStart(2, '0');
    const b = imageData.data[pixelPos + 2].toString(16).padStart(2, '0');
    const a = imageData.data[pixelPos + 3];

    // Only consider non-transparent pixels
    if (a < 128) return null;

    const color = r + g + b;
    return COLOR_TO_REGION[color] || null;
  }, [imageData]);

  // Handle mouse move for hover detection
  const handleMouseMove = useCallback((event: React.MouseEvent) => {
    if (!isImageLoaded || !mapContainerRef.current) return;

    const rect = mapContainerRef.current.getBoundingClientRect();
    const x = Math.floor(event.clientX - rect.left - displayRect.left);
    const y = Math.floor(event.clientY - rect.top - displayRect.top);

    // Check bounds within the displayed map area
    if (x < 0 || x >= displayRect.width || y < 0 || y >= displayRect.height) {
      setHoveredRegion(null);
      return;
    }

    const regionId = getRegionFromPixel(x, y);
    setHoveredRegion(regionId);
  }, [isImageLoaded, getRegionFromPixel, displayRect]);

  // Handle click
  const handleClick = useCallback((event: React.MouseEvent) => {
    // During event phase, completely disable interaction
    if (currentPhase === 'event') {
      return;
    }

    // Company phase - allow region selection
    if (!isImageLoaded || !mapContainerRef.current) return;

    const rect = mapContainerRef.current.getBoundingClientRect();
    const x = Math.floor(event.clientX - rect.left - displayRect.left);
    const y = Math.floor(event.clientY - rect.top - displayRect.top);

    // Check bounds within the displayed map area
    if (x < 0 || x >= displayRect.width || y < 0 || y >= displayRect.height) {
      onRegionSelect(null);
      return;
    }

    const regionId = getRegionFromPixel(x, y);
    
    if (regionId) {
      // In company phase, select the region for editing
      onRegionSelect(regionId);
    } else {
      onRegionSelect(null);
    }
  }, [isImageLoaded, getRegionFromPixel, currentPhase, onRegionSelect, displayRect]);

  // Calculate base image onLoad
  const handleBaseImageLoad = () => {
    if (baseImageRef.current) {
      setNaturalSize({
        width: baseImageRef.current.naturalWidth,
        height: baseImageRef.current.naturalHeight
      });
    }
    calculateDisplayRect();
  };
  
  // Render orders for a specific region
  const renderOrders = (regionId: string) => {
    const regionOrders = orderPositions[regionId] || [];
    return regionOrders.map((orderPos) => {
      const order = gameState.orders[orderPos.orderId];
      if (!order) return null;

      const absolutePos = getAbsolutePosition(orderPos);
      
      return (
        <div
          key={`order-${orderPos.orderId}`}
          className="absolute cursor-pointer transition-transform hover:scale-110"
          style={{
            left: absolutePos.x - 12,
            top: absolutePos.y - 12,
            zIndex: 30
          }}
          onClick={(e) => handleOrderClick(orderPos.orderId, e)}
          title={`Order ${orderPos.orderId} - £${order.price} - ${order.open ? 'OPEN' : 'CLOSED'}`}
        >
          {!order.open && (
            <img 
              src={closedOrderImg} 
              alt="Closed Order" 
              className="w-6 h-6" 
            />
          )}
          {order.open && (
            <img 
              src={closedOrderImg} 
              alt="Open Order" 
              className="w-6 h-6 opacity-5" 
            />
          )}
        </div>
      );
    });
  };

  // Render towers for all regions
  const renderTowers = () => {
    const flagImages = {
      silver: flagImg,
      gold: flagGoldImg, 
      bronze: flagBronzeImg
    };

    const flagStarImages = {
      silver: flagStarImg,
      gold: flagGoldStarImg, 
      bronze: flagBronzeStarImg
    };

    return Object.values(towerPositions).map((towerPos) => {
      const region = gameState.regions[towerPos.regionId];
      if (!region || region.towerHeight === 0) return null;

      const absolutePos = getAbsolutePosition(towerPos);
      
      const currentFlagImg = flagImages[region.flagColor] || flagImages.silver;
      const currentFlagStarImg = flagStarImages[region.flagColor] || flagStarImages.silver;

      const flagConfigs = [
        { condition: region.towerHasFlag, img: currentFlagImg, alt: "Flag" },
        { condition: region.towerHasFlagStar, img: currentFlagStarImg, alt: "Star Flag" }
      ];

      return (
        <div
          key={`tower-${towerPos.regionId}`}
          className="absolute"
          style={{
            left: absolutePos.x - 20,
            top: absolutePos.y - 20,
            zIndex: 25
          }}
          title={`${region.name} Tower - Height: ${region.towerHeight}`}
        >
          <div className="flex items-center">
            {/* Tower with height */}
            <div className="relative">
              <img 
                src={towerSimpleImg} 
                alt="Tower" 
                className="w-9 h-9" 
              />
              <div className="absolute inset-0 flex items-center justify-center text-white font-bold text-xl pointer-events-none">
                {region.towerHeight}
              </div>
            </div>
            
            {/* Flags */}
            <div>
              {flagConfigs.map((flag, index) => 
                flag.condition && (
                  <img 
                    key={`flag-${index}`}
                    src={flag.img} 
                    alt={flag.alt} 
                    className="w-6 h-6" 
                  />
                )
              )}
            </div>
          </div>
        </div>
      );
    });
  };

  // Render governor overlays for company-controlled regions
  const renderGovernorOverlays = () => {
    return Object.values(gameState.regions)
      .filter(region => region.companyControlled)
      .map(region => {
        const towerPos = towerPositions[region.id];
        if (!towerPos) return null;

        const absolutePos = getAbsolutePosition(towerPos);
        
        return (
          <div
            key={`governor-${region.id}`}
            className="absolute"
            style={{
              left: absolutePos.x - 20,
              top: absolutePos.y - 20,
              zIndex: 20
            }}
          >
            <img 
              src={governorOverlayImg} 
              alt="Governor" 
              className="w-9 h-9 opacity-70" 
            />
          </div>
        );
      });
  };
  const renderUnrest = () => {
    return Object.values(unrestPositions).map((UnrestPos) => {
      const region = gameState.regions[UnrestPos.regionId];
      if (!region || region.unrest === 0) return null;

      const absolutePos = getAbsolutePosition(UnrestPos);
      
      return (
        <div
          key={`unrest-${UnrestPos.regionId}`}
          className="absolute"
          style={{
            left: absolutePos.x - 20,
            top: absolutePos.y - 20,
            zIndex: 25
          }}
          title={`${region.name} Unrest: ${region.unrest}`}
        >
          <img 
            src={unrestImg} 
            alt="Unrest" 
            className="w-7 h-7" 
          />
          <div className="absolute inset-0 flex items-center justify-center text-white font-bold text-xl pointer-events-none">
            {region.unrest}
          </div>
        </div>
      );
    });
  };
  const renderElephant = (regionIdFront: string, regionIdBack: string) => {
    const elephant = elephantPositions[regionIdFront+regionIdBack][0] || [];
    if (!elephant) return null;

    const absolutePos = getAbsolutePosition(elephant);
    
    return (
      <div
        key={`elephant-facing-${elephant.regionIdFront}-from-${elephant.regionIdBack}`}
        className="absolute"
        style={{
          left: absolutePos.x - 20,
          top: absolutePos.y - 20,
          zIndex: 56
        }}
        title={`${elephant.regionIdFront} facing Elephant from ${elephant.regionIdBack}`}
      >
        <img 
          src={elephantImg} 
          alt="Elephant" 
          className={`w-7 h-10 transform ${elephant.rotation}`} 
        />
      </div>
    );
  };
  
  // Don't render detailed view anymore since we're handling everything on the main map
  if (isZoomed && selectedRegion) {
    return (
      <div className="h-full flex flex-col p-4 bg-gray-50">
        <div className="flex justify-between items-center mb-4">
          <button 
            onClick={() => setIsZoomed(false)}
            className="px-4 py-2 bg-amber-500 text-white rounded-lg hover:bg-amber-600 transition-colors"
          >
            Back to Map
          </button>
          <h2 className="text-2xl font-bold text-gray-800 capitalize">
            {gameState.regions[selectedRegion].name}
          </h2>
        </div>
        
        <div className="flex-1 bg-white rounded-lg border-2 border-amber-200 p-4 flex items-center justify-center">
          <p className="text-gray-500">Region details are now managed in the Company Phase panel</p>
        </div>
      </div>
    );
  }

  // Render overview map
  return (
    <div 
      ref={mapContainerRef}
      className="h-full relative bg-gray-100 rounded-lg overflow-hidden"
      onMouseMove={handleMouseMove}
      onClick={handleClick}
    >
      {/* Hidden canvas for hit detection */}
      <canvas 
        ref={canvasRef} 
        style={{ display: 'none' }}
      />
      
      {/* Base Map */}
      <img 
        ref={baseImageRef}
        src={baseMapImage} 
        alt="India Map"
        className="w-full h-full object-contain"
        style={{ cursor: currentPhase === 'company' ? 'pointer' : 'default' }}
        onLoad={handleBaseImageLoad}
      />
      
      {/* Hover Region Overlay */}
      {hoveredRegion && currentPhase === 'company' && (
        <div 
          className="absolute pointer-events-none"
          style={{
            left: `${displayRect.left}px`,
            top: `${displayRect.top}px`,
            width: `${displayRect.width}px`,
            height: `${displayRect.height}px`,
          }}
        >
          <img 
            src={regionOverlayImages[hoveredRegion]}
            alt={`${hoveredRegion} overlay`}
            className="w-full h-full object-contain opacity-10 brightness-125"
          />
        </div>
      )}

      {/* Selected Region Overlay */}
      {selectedRegion && currentPhase === 'company' && (
        <div 
          className="absolute pointer-events-none"
          style={{
            left: `${displayRect.left}px`,
            top: `${displayRect.top}px`,
            width: `${displayRect.width}px`,
            height: `${displayRect.height}px`,
          }}
        >
          <img 
            src={detailedRegionImages[selectedRegion]}
            alt={`${selectedRegion} selected`}
            className="w-full h-full object-contain opacity-100 brightness-125"
          />
        </div>
      )}

      {/* Render Elephant */}
      {renderElephant(gameState.elephant.headRegion, gameState.elephant.tailRegion)}

      {/* Render Orders */}
      {Object.keys(gameState.regions).map(regionId => 
        renderOrders(regionId)
      )}

      {/* Render Towers */}
      {renderTowers()}

      {/* Render Unrest */}
      {renderUnrest()}

      {/* Render Governor Overlays */}
      {renderGovernorOverlays()}
      
            {/* Visual feedback for hovered region */}
      {hoveredRegion && currentPhase === 'company' && (
        <div className="absolute top-4 left-4 bg-black bg-opacity-70 text-white p-2 rounded text-sm" style={{zIndex: 100}}>
          {gameState.regions[hoveredRegion].name}
          {selectedRegion === hoveredRegion }
        </div>
      )}

      {/* Phase indicator */}
      <div className="absolute bottom-4 left-4 bg-black bg-opacity-70 text-white p-2 rounded text-sm" style={{zIndex: 100}}>
        {currentPhase === 'event' ? 'Event Phase' : 'Company Phase'}
      </div>

      {/* Debug info - remove in production */}
      {/* {process.env.NODE_ENV === 'development' && (
        <div className="absolute bottom-4 right-4 bg-black bg-opacity-70 text-white p-2 rounded text-xs">
          Container: {Math.round(containerSize.width)}x{Math.round(containerSize.height)}
          <br />
          Display: {Math.round(displayRect.width)}x{Math.round(displayRect.height)}
          <br />
          Offset: {Math.round(displayRect.left)},{Math.round(displayRect.top)}
        </div>
      )} */}
    </div>
  );
};

export default MapView;